parameters.jsCode:
const s = $('Find settings').first().json;
const products = $('Get products to check').first().json.data.products.nodes;
// A product that already has a card waiting, or images on their way, is left alone.
const open = new Set($input.all().map(i => i.json.product_id).filter(Boolean));
const out = [];
for (const p of products) {
  if (open.has(p.id)) continue;
  const v = p.variants.nodes[0] || {};
  const images = p.media.nodes.filter(m => m.mediaContentType === 'IMAGE');
  out.push({ json: {
    product_id: p.id, title: p.title, vendor: p.vendor,
    mpn: (p.mpn || v.mpn || {}).value || '',
    gtin: v.barcode || '', sku: v.sku || '',
    page_url: (p.page || {}).value || '',
    current: images.map(m => ({ id: m.id, status: m.status, alt: m.alt || '', url: m.preview && m.preview.image ? m.preview.image.url : '' })),
    // A product whose only image FAILED (a dead supplier link) counts as having none.
    no_image: images.filter(m => m.status !== 'FAILED').length === 0
  } });
  if (out.length >= s.batch_size) break;
}
return out;

const s = $('Find settings').first().json;
const p = $('Loop over products').first().json;
const vendor = String(p.vendor || '').trim().toLowerCase();
const brands = $('Brand domains').all().map(i => i.json).filter(b => b.domain && String(b.brand || '').trim().toLowerCase() === vendor);
const model = String(p.mpn || '').trim();
const slug = model.toLowerCase().replace(/\(.*?\)/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
// 1. a manufacturer_url metafield, 2. the brand's URL pattern, 3. a search (optional)
let page_url = p.page_url;
if (!page_url && slug) {
  const b = brands.find(x => x.url_pattern);
  if (b) page_url = b.url_pattern.replace('{model}', slug);
}
return [{ json: { ...p, page_url,
  brand_domains: brands.map(b => b.domain.toLowerCase()),
  search: !page_url && s.use_dataforseo === true && !!model && brands.length > 0,
  // Brand and model, no site: operator: DataForSEO bills operator queries at five times the price, and Match the page keeps brand domains only.
  query: (code => code.toLowerCase().startsWith(vendor) ? code : p.vendor + ' ' + code)(model.replace(/\(.*?\)/g, '').trim()) } }];

const p = $('Pick the page').first().json;
const task = ($json.tasks || [])[0] || {};
const items = ((task.result || [])[0] || {}).items || [];
// DataForSEO sometimes answers a task with an error over HTTP 200 (40101 "Internal SE Server Error"): try again next run.
const search_error = task.status_code === 20000 ? '' : String(task.status_message || $json.status_message || ($json.error || {}).message || 'search failed');
const norm = t => String(t || '').toUpperCase().replace(/\+/g, 'PLUS');
const compact = t => norm(t).replace(/[^A-Z0-9]/g, '');
const code = norm(p.mpn).replace(/\(.*?\)/g, '').trim();
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const inTitle = t => new RegExp('(^|[^A-Z0-9])' + esc(code) + '($|[^A-Z0-9])').test(norm(t));
const inPath = u => u.replace(/^https?:\/\/[^\/]+/i, '').split(/[\/?#.]/).map(compact).includes(compact(code));
const host = u => ((u.match(/^https?:\/\/([^\/?#]+)/i) || [])[1] || '').toLowerCase();
const onBrand = u => p.brand_domains.some(d => host(u) === d || host(u).endsWith('.' + d));
const hit = items.find(i => i.type === 'organic' && i.url && onBrand(i.url) && (inPath(i.url) || inTitle(i.title)));
return [{ json: { ...p, page_url: hit ? hit.url : '', search_error, search_cost: $json.cost || 0 } }];

const s = $('Find settings').first().json;
const p = $input.first().json;
const out = { ...p, page_images: [], page_note: '' };
if (!p.page_url) { out.page_note = p.search_error ? 'search failed: ' + p.search_error + ', trying again next run' : 'no manufacturer page'; return [{ json: out }]; }
const m = /^(https?:\/\/([^\/?#]+))([^?#]*)/i.exec(p.page_url);
if (!m) { out.page_note = 'bad page url'; return [{ json: out }]; }
const get = (url, timeout = 30000) => this.helpers.httpRequest({ url, timeout, json: false,
  headers: { 'User-Agent': s.user_agent }, returnFullResponse: true, ignoreHttpStatusErrors: true });

// 1. robots.txt (RFC 9309): 4xx means no rules, 5xx or unreachable means stay away, longest match wins
let rules = [];
try {
  const r = await get(m[1] + '/robots.txt', 10000);
  if (r.statusCode >= 500) rules = [{ allow: false, path: '/' }];
  else if (r.statusCode < 400) {
    let mine = false, inRules = false;
    for (const raw of String(r.body || '').split(/\r?\n/)) {
      const line = raw.replace(/#.*/, '').trim();
      const i = line.indexOf(':'); if (i < 0) continue;
      const k = line.slice(0, i).trim().toLowerCase(), v = line.slice(i + 1).trim();
      if (k === 'user-agent') { if (inRules) { mine = false; inRules = false; } mine = mine || v === '*'; }
      else if (k === 'allow' || k === 'disallow') { inRules = true; if (mine && v) rules.push({ allow: k === 'allow', path: v }); }
    }
  }
} catch (e) { rules = [{ allow: false, path: '/' }]; }
const test = (rule, path) => { const end = rule.endsWith('$'); const body = end ? rule.slice(0, -1) : rule;
  return new RegExp('^' + body.split('*').map(x => x.replace(/[.+?^${}()|[\]\\]/g, '\\$&')).join('.*') + (end ? '$' : '')).test(path); };
let best = null;
for (const r of rules) if (test(r.path, m[3] || '/') && (!best || r.path.length > best.path.length || (r.path.length === best.path.length && r.allow))) best = r;
if (best && !best.allow) { out.page_note = 'robots.txt disallows ' + best.path; return [{ json: out }]; }

// 2. the page
let html = '';
try { const r = await get(p.page_url); if (r.statusCode < 400) html = String(r.body || ''); else out.page_note = 'page returned ' + r.statusCode; }
catch (e) { out.page_note = 'page fetch failed'; }

// 3. og:image, JSON-LD Product.image, then <img> (largest srcset entry first)
const abs = u => { u = String(u || '').trim().replace(/&amp;/g, '&'); if (u.startsWith('//')) return 'https:' + u; if (u.startsWith('/')) return m[1] + u; return u; };
const found = [];
const add = (u, alt, how) => { u = abs(u); if (/^https?:\/\//i.test(u)) found.push({ url: u, alt: String(alt || '').slice(0, 200), how }); };
for (const x of html.matchAll(/<meta[^>]+(?:property|name)=["']og:image(?::secure_url)?["'][^>]*>/gi)) add((x[0].match(/content=["']([^"']+)/i) || [])[1], 'og:image', 'og');
for (const x of html.matchAll(/<script[^>]+application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
  let data; try { data = JSON.parse(x[1]); } catch (e) { continue; }
  for (const n of [].concat(data['@graph'] || data)) {
    if (!n || !String(n['@type'] || '').includes('Product')) continue;
    for (const im of [].concat(n.image || [])) add(typeof im === 'string' ? im : (im.contentUrl || im.url), n.name, 'jsonld');
  }
}
for (const x of html.matchAll(/<img\b[^>]*>/gi)) {
  const tag = x[0];
  const alt = (tag.match(/\balt=["']([^"']*)/i) || [])[1] || '';
  const srcset = (tag.match(/\b(?:data-)?srcset=["']([^"']+)/i) || [])[1];
  if (srcset) {
    const big = srcset.split(',').map(e => e.trim().split(/\s+/)).map(([u, w]) => ({ u, w: parseInt(w, 10) || 0 })).sort((a, b) => b.w - a.w)[0];
    if (big && big.u) { add(big.u, alt, 'img'); continue; }
  }
  add((tag.match(/\b(?:data-src|src)=["']([^"']+)/i) || [])[1], alt, 'img');
}

// 4. the brand's own domains and their CDNs only, never a retailer
const host = u => ((u.match(/^https?:\/\/([^\/?#]+)/i) || [])[1] || '').toLowerCase();
const pageDomain = m[2].toLowerCase().replace(/^www\./, '');
const own = u => p.brand_domains.concat(pageDomain).some(d => host(u) === d || host(u).endsWith('.' + d));
const seen = new Set();
out.page_images = found.filter(f => own(f.url) && !seen.has(f.url) && seen.add(f.url)).slice(0, 40);
if (!out.page_note && !out.page_images.length) out.page_note = 'no images on the brand page';
return [{ json: out }];

const s = $('Find settings').first().json;
const p = $input.first().json;
const norm = t => String(t || '').toLowerCase().replace(/[^a-z0-9]/g, '');
// Access tokens (such as content_token) come off every URL before it's stored or shown.
// Plain string replace: the Code node sandbox has no URL class.
const keys = String(s.strip_query_params || '').split(',').map(k => k.trim()).filter(Boolean);
const strip = u => { let x = String(u); for (const k of keys) x = x.replace(new RegExp('([?&])' + k.replace(/[^\w-]/g, '') + '=[^&#]*&?', 'g'), '$1'); return x.replace(/[?&]$/, ''); };
const JUNK = /(logo|favicon|sprite|icon|banner|header|footer|nav[-_]|megamenu|social|facebook|twitter|instagram|youtube|linkedin|badge|award|flag|payment|cookie|placeholder|spacer|loading|spinner|arrow|chevron|avatar|swatch|watermark|newsletter|qr[-_]?code|app[-_]?store|google[-_]?play|\.svg(\?|$)|data:image)/i;
const ICON = /[-_](16|24|32|48|64|96|128)\.(png|jpe?g|webp|gif)($|[?])/i;

// Real dimensions from the file header (a ranged GET), never from a size in the URL.
// 404 or 410: gone, drop it. Anything else that fails (a 403 hotlink guard, a timeout) keeps the image with size unknown.
const dims = async (url) => {
  try {
    const raw = await this.helpers.httpRequest({ url, headers: { Range: 'bytes=0-65535', 'User-Agent': s.user_agent }, encoding: 'arraybuffer', timeout: 15000 });
    const b = Buffer.from(raw);
    if (b.length > 24 && b[0] === 0x89 && b[1] === 0x50) return { w: b.readUInt32BE(16), h: b.readUInt32BE(20) };
    if (b.length > 10 && b.toString('ascii', 0, 4) === 'GIF8') return { w: b.readUInt16LE(6), h: b.readUInt16LE(8) };
    if (b.length > 30 && b.toString('ascii', 0, 4) === 'RIFF' && b.toString('ascii', 8, 12) === 'WEBP') {
      const c = b.toString('ascii', 12, 16);
      if (c === 'VP8 ') return { w: b.readUInt16LE(26) & 0x3fff, h: b.readUInt16LE(28) & 0x3fff };
      if (c === 'VP8L') return { w: 1 + (((b[22] & 0x3f) << 8) | b[21]), h: 1 + (((b[24] & 0x0f) << 10) | (b[23] << 2) | ((b[22] & 0xc0) >> 6)) };
      if (c === 'VP8X') return { w: 1 + b.readUIntLE(24, 3), h: 1 + b.readUIntLE(27, 3) };
    }
    if (b[0] === 0xff && b[1] === 0xd8) {
      let i = 2;
      while (i + 9 < b.length) {
        if (b[i] !== 0xff) { i++; continue; }
        const mk = b[i + 1];
        if (mk >= 0xc0 && mk <= 0xcf && mk !== 0xc4 && mk !== 0xc8 && mk !== 0xcc) return { w: b.readUInt16BE(i + 7), h: b.readUInt16BE(i + 5) };
        const len = b.readUInt16BE(i + 2); if (len < 2) break;
        i += 2 + len;
      }
    }
    return {};
  } catch (e) {
    const code = Number(e && (e.httpCode || e.statusCode || (e.response && e.response.status))) || 0;
    return { dead: code === 404 || code === 410 };
  }
};

const cands = [];
for (const c of p.page_images || []) {
  if (JUNK.test(c.url) || ICON.test(c.url) || JUNK.test(c.alt)) continue;
  cands.push({ url: strip(c.url), source: c.how === 'img' ? 'page' : 'page_' + c.how, alt: c.alt, base: c.how === 'img' ? 50 : 65 });
}
// The same shot in several sizes or formats collapses to one (the large copy wins); numbered angles (-1, -2) stay.
const hint = u => /(large|zoom|big|original|full)/i.test(u) ? 0 : /(thumb|small|mini|tiny)/i.test(u) ? 2 : 1;
cands.sort((a, b) => hint(a.url) - hint(b.url));
const key = u => u.split('?')[0].toLowerCase()
  .replace(/\/cache\/[0-9a-f]{32}\//, '/')
  .replace(/[-_]?\d{2,4}[x×]\d{2,4}/g, '')
  .replace(/[-_](large|medium|normal|small|thumb|thumbnail|zoom|big)(?=[-_.])/g, '')
  .replace(/[-_]\d{8,}[a-z]?(?=\.[a-z0-9]+$)/, '')
  .replace(/\.[a-z0-9]+$/, '');
const seen = new Set();
const uniq = cands.filter(c => { const k = key(c.url); if (seen.has(k)) return false; seen.add(k); return true; }).slice(0, 25);

const tokens = [norm(String(p.mpn).replace(/\(.*?\)/g, ''))]
  .concat(String(p.title).split(/[\s,\/]+/).map(norm).filter(t => /\d/.test(t) && /[a-z]/.test(t)))
  .filter(t => t.length >= 4);
let dropped_small = 0, dropped_dead = 0;
for (const c of uniq) {
  const d = await dims(c.url);
  Object.assign(c, { width: d.w || null, height: d.h || null, dead: !!d.dead });
  const reasons = [c.source];
  let score = c.base;
  if (tokens.some(t => norm(c.url + ' ' + c.alt).includes(t))) { score += 20; reasons.push('model in name'); }
  if (c.width && c.height) {
    const short = Math.min(c.width, c.height), long = Math.max(c.width, c.height);
    score += Math.min(short, 1600) / 40;
    reasons.push(c.width + 'x' + c.height);
    if (long / short > 2.5) { score -= 30; reasons.push('very wide or tall'); }
    c.too_small = short < s.min_short_side;
    c.tiny = short < s.fallback_min_side;
  } else { score -= 10; reasons.push('size unknown'); c.too_small = false; c.tiny = false; }
  c.score = Math.round(score);
  c.reasons = reasons;
  if (c.dead) dropped_dead++;
  else if (c.tiny || (c.too_small && !p.no_image)) dropped_small++;
}
// Any manufacturer image beats none, so a product with no working image gets anything above fallback_min_side.
const ranked = uniq.filter(c => !c.dead && !c.tiny && (p.no_image || !c.too_small))
  .sort((a, b) => b.score - a.score).slice(0, s.max_candidates);
return [{ json: { ...p, ranked, considered: uniq.length, dropped_small, dropped_dead } }];

const s = $('Find settings').first().json;
const p = $input.first().json;
// Basic LLM Chain reads { and } as template variables, so they come out of the title and vendor.
return p.ranked.slice(0, s.vision_top_n).map((c, idx) => ({ json: {
  idx, url: c.url,
  title: String(p.title).replace(/[{}]/g, ''), vendor: String(p.vendor).replace(/[{}]/g, ''),
  vision_url: 'https://wsrv.nl/?url=' + encodeURIComponent(c.url) + '&w=768&h=768&fit=contain&cbg=white&output=jpg'
} }));

const s = $('Find settings').first().json;
const p = $('Rank candidates').first().json;
const queue = p.ranked.length ? $('Vision queue').all().map(i => i.json) : [];
const answers = p.ranked.length ? $input.all().map(i => i.json) : [];
// The chain hands back the parsed object when the model replies with bare JSON, and { text } when it
// wraps the JSON in a code fence (Ollama Cloud does both, Output Format JSON or not), so read either.
const parse = r => { if (!r || r.error) return null; if (r.text === undefined) return r.alt_text !== undefined ? r : null;
  const t = String(r.text); try { return JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); } catch (e) { return null; } };
const vis = {};
answers.forEach((r, i) => { if (queue[i]) vis[queue[i].idx] = parse(r); });

// The answers move the score. Added text or the wrong product unticks the image; packaging and lifestyle stay ticked but sort lower.
const ranked = p.ranked.map((c, idx) => {
  const v = vis[idx] || null;
  const c2 = { ...c, reasons: [...c.reasons], vision: v, selected: true, primary: false };
  if (v) {
    if (v.white_background === true) { c2.score += 25; c2.reasons.push('white background'); }
    if (v.single_product === true) c2.score += 10;
    if (v.packaging === true) { c2.score -= 15; c2.reasons.push('packaging'); }
    if (v.lifestyle === true) { c2.score -= 10; c2.reasons.push('lifestyle'); }
    if (v.added_text === true) { c2.score -= 40; c2.reasons.push('added text'); c2.selected = false; }
    if (v.matches === false) { c2.score -= 50; c2.reasons.push('may not match'); c2.selected = false; }
  } else if (idx < s.vision_top_n) c2.reasons.push('not checked');
  return c2;
}).sort((a, b) => b.score - a.score);

// Alt text checks. A failed alt falls back to "<title>, <view>" (or "photo N"); a repeat gets its view added so no two images share one.
const title = String(p.title || '').trim();
const name = String(p.mpn || p.vendor || '').replace(/\(.*?\)/g, '').trim();
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const used = new Set();
ranked.forEach((c, k) => {
  const v = c.vision || {};
  const view = String(v.view || '').trim();
  let a = String(v.alt_text || '').replace(/\s+/g, ' ').trim().replace(/^["']|["']$/g, '');
  const problems = [];
  if (!a) problems.push('empty');
  if (a.length > s.max_alt_length) problems.push('too long');
  if (/^(an? )?(image|picture|photo) of\b/i.test(a)) problems.push('starts with image of');
  if (a.toLowerCase() === title.toLowerCase()) problems.push('same as the title');
  if (name && (a.match(new RegExp(esc(name), 'gi')) || []).length > 1) problems.push('names the product twice');
  if (problems.length) a = title + ', ' + (view || 'photo ' + (k + 1));
  if (used.has(a.toLowerCase())) a = a.replace(/[.\s]+$/, '') + ', ' + (view || 'view ' + (k + 1));
  used.add(a.toLowerCase());
  c.alt = a;
  c.alt_problems = problems.join('; ');
});

const selected = ranked.filter(c => c.selected);
return [{ json: {
  product_id: p.product_id, title: p.title, vendor: p.vendor, mpn: p.mpn, page_url: p.page_url,
  status: selected.length ? 'review' : 'skipped',
  // a failed search keeps the tag, so the next run tries again
  retry: !selected.length && !!p.search_error,
  error: selected.length ? '' : (p.considered ? 'no usable image' : 'no manufacturer image found') + (p.page_note ? ' (' + p.page_note + ')' : ''),
  candidates: JSON.stringify(ranked.map(c => ({ url: c.url, source: c.source, width: c.width, height: c.height, score: c.score,
    reasons: c.reasons, selected: c.selected, primary: false, alt: c.alt, alt_problems: c.alt_problems, view: (c.vision || {}).view || '' }))),
  current: JSON.stringify(p.current),
  updated_at: new Date().toISOString()
} }];

const s = $('Find settings').first().json;
const r = $('Score and write alt').first().json;
const cands = JSON.parse(r.candidates);
const cur = JSON.parse(r.current).filter(m => m.url && m.status !== 'FAILED')[0];
// Slack caps a checkbox group at ten options: up to nine new images plus Current.
const pick = cands.map((c, i) => ({ c, i })).filter(x => x.c.selected).slice(0, 9);
const n = pick.length;
const id = r.product_id.split('/').pop();
const opt = (x, k) => ({ text: { type: 'plain_text', text: String(k + 1) }, value: 'i' + x.i });
const curOpt = cur ? [{ text: { type: 'plain_text', text: 'Current (untick to remove)' }, value: 'current' }] : [];
const links = [
  { type: 'button', text: { type: 'plain_text', text: 'Shopify' }, url: 'https://admin.shopify.com/store/' + s.admin_store_handle + '/products/' + id },
  ...(r.page_url ? [{ type: 'button', text: { type: 'plain_text', text: 'Manufacturer' }, url: r.page_url }] : []),
  { type: 'button', text: { type: 'plain_text', text: 'Google' }, url: 'https://www.google.com/search?q=' + encodeURIComponent(r.title + ' ' + (r.mpn || '')) }
];
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: r.title.slice(0, 150) } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: (r.mpn ? '`' + r.mpn + '` · ' : '') + '*' + n + '* image' + (n === 1 ? '' : 's') + ' to add'
    + (cur ? ' (*Current* is the main image today)' : ' (the product has no working image)') + '. Untick any you don\'t want, pick a main image if it should change, then Approve.' }] },
  { type: 'actions', elements: links },
  // Placeholder: Add sheet to card swaps in the contact sheet, or keeps this top pick if the sheet fails.
  { type: 'image', image_url: cands[pick[0].i].url, alt_text: n + ' images for ' + r.title.slice(0, 100), title: { type: 'plain_text', text: n + ' image' + (n === 1 ? '' : 's') + ', numbered' } },
  { type: 'input', block_id: 'keep', optional: true, label: { type: 'plain_text', text: 'Images to add' },
    element: { type: 'checkboxes', action_id: 'keep', options: curOpt.concat(pick.map(opt)), initial_options: curOpt.concat(pick.map(opt)) } },
  { type: 'input', block_id: 'main', optional: true, label: { type: 'plain_text', text: 'Main image' },
    element: { type: 'radio_buttons', action_id: 'main', initial_option: { text: { type: 'plain_text', text: 'Keep current' }, value: 'keep' },
      options: [{ text: { type: 'plain_text', text: 'Keep current' }, value: 'keep' }].concat(pick.map(opt)) } },
  { type: 'actions', block_id: 'decide', elements: [
    { type: 'button', style: 'primary', text: { type: 'plain_text', text: 'Approve' }, action_id: 'img_approve', value: r.product_id },
    { type: 'button', style: 'danger', text: { type: 'plain_text', text: 'Reject' }, action_id: 'img_reject', value: r.product_id }
  ] }
];
return [{ json: { product_id: r.product_id, channel: s.slack_channel, text: 'Images to review: ' + r.title, blocks,
