const s = $('Publish settings').first().json;
const row = $('Pick one').first().json;
const product = ($json.data || {}).product || {};
const nodes = (product.media || {}).nodes || [];
const live = new Map(nodes.map(n => [n.id, n.status]));
// A source is already on the product when the log has it and its media still exists and hasn't FAILED.
const logs = $('Already pushed').all().map(i => i.json).filter(l => l.source_hash && live.has(l.media_id) && live.get(l.media_id) !== 'FAILED');
const present = new Map(logs.map(l => [l.source_hash, l.media_id]));
const hash = t => { let h = 0; for (const ch of String(t)) h = (Math.imul(31, h) + ch.charCodeAt(0)) | 0; return (h >>> 0).toString(16); };
const slug = String(row.title || 'product').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60) || 'product';
const chosen = JSON.parse(row.candidates || '[]').filter(c => c.selected)
  .sort((a, b) => (b.primary === true) - (a.primary === true))
  .map(c => ({ ...c, source_hash: hash(c.url) }));
// wsrv.nl ignores the path, so the file name goes there and Shopify names the file after it.
const media = chosen.filter(c => !present.has(c.source_hash)).map((c, k) => {
  const name = slug + (k ? '-' + (k + 1) : '');
  return { source_url: c.url, source_hash: c.source_hash, primary: !!c.primary, alt: c.alt, filename: name + '.jpg',
    originalSource: 'https://wsrv.nl/' + name + '.jpg?url=' + encodeURIComponent(c.url) + '&w=' + s.image_size + '&h=' + s.image_size + '&fit=contain&cbg=' + s.pad_colour + '&output=jpg' };
});
const images = nodes.filter(n => n.mediaContentType === 'IMAGE');
const main = images[0];
const presentReady = chosen.filter(c => present.has(c.source_hash)).every(c => live.get(present.get(c.source_hash)) === 'READY');
return [{ json: {
  product_id: row.product_id, title: row.title, card_channel: row.card_channel, card_ts: row.card_ts, store_url: product.onlineStoreUrl || '',
  before_ids: nodes.map(n => n.id), media, has_new: media.length > 0, present_ready: presentReady,
  // the reviewer unticked Current, or the current main image is a FAILED (dead) link
  remove_media_id: main && (row.remove_current === true || row.remove_current === 'true' || main.status === 'FAILED') ? main.id : '',
  // Shopify won't detach a FAILED file (NON_READY_STATE), so a dead one is deleted instead.
  remove_failed: !!main && main.status === 'FAILED'
} }];

const s = $('Publish settings').first().json;
const tok = $('Get Shopify token for Publish').first().json;
const p = $input.first().json;
const gql = (query, variables) => this.helpers.httpRequest({ method: 'POST', url: 'https://' + s.store_domain + '/admin/api/2026-10/graphql.json',
  headers: { 'X-Shopify-Access-Token': tok.access_token }, body: { query, variables }, json: true, timeout: 60000 });
const out = [];
for (const m of p.media) {
  // Fetching the wsrv.nl copy proves wsrv.nl can read the source, and warms its cache before Shopify asks.
  let ok = false;
  try { await this.helpers.httpRequest({ url: m.originalSource, encoding: 'arraybuffer', timeout: 45000 }); ok = true; } catch (e) {}
  if (ok) { out.push({ json: { ...m, blocked: false } }); continue; }
  // Blocked: the brand's server refuses wsrv.nl. n8n downloads and pads the original, then stages it on Shopify.
  try {
    const r = await gql('mutation Stage($input: [StagedUploadInput!]!) { stagedUploadsCreate(input: $input) { stagedTargets { url resourceUrl } userErrors { field message } } }',
      { input: [{ resource: 'IMAGE', filename: m.filename, mimeType: 'image/jpeg', httpMethod: 'PUT' }] });
    const t = (((r.data || {}).stagedUploadsCreate || {}).stagedTargets || [])[0];
    if (!t || !t.url) throw new Error('no staged target');
    out.push({ json: { ...m, blocked: true, upload_url: t.url, resource_url: t.resourceUrl } });
  } catch (e) { out.push({ json: { ...m, blocked: false, stage_error: String(e.message || e).slice(0, 120) } }); }
}
return out;

const s = $('Publish settings').first().json;
const S = Number(s.image_size);
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  if (!it.binary || !it.binary.data) { out.push({ json: { ...it.json, pad_error: 'download failed' } }); continue; }
  // Real size from the file header, then the size it will have once it fits inside the square.
  const b = await this.helpers.getBinaryDataBuffer(i, 'data');
  let w = 0, h = 0;
  if (b[0] === 0x89 && b[1] === 0x50) { w = b.readUInt32BE(16); h = b.readUInt32BE(20); }
  else if (b.toString('ascii', 0, 4) === 'GIF8') { w = b.readUInt16LE(6); h = b.readUInt16LE(8); }
  else if (b.toString('ascii', 0, 4) === 'RIFF' && b.toString('ascii', 8, 12) === 'WEBP') {
    const c = b.toString('ascii', 12, 16);
    if (c === 'VP8 ') { w = b.readUInt16LE(26) & 0x3fff; h = b.readUInt16LE(28) & 0x3fff; }
    if (c === 'VP8L') { w = 1 + (((b[22] & 0x3f) << 8) | b[21]); h = 1 + (((b[24] & 0x0f) << 10) | (b[23] << 2) | ((b[22] & 0xc0) >> 6)); }
    if (c === 'VP8X') { w = 1 + b.readUIntLE(24, 3); h = 1 + b.readUIntLE(27, 3); }
  } else if (b[0] === 0xff && b[1] === 0xd8) {
    let k = 2;
    while (k + 9 < b.length) {
      if (b[k] !== 0xff) { k++; continue; }
      const mk = b[k + 1];
      if (mk >= 0xc0 && mk <= 0xcf && mk !== 0xc4 && mk !== 0xc8 && mk !== 0xcc) { h = b.readUInt16BE(k + 5); w = b.readUInt16BE(k + 7); break; }
      k += 2 + b.readUInt16BE(k + 2);
    }
  }
  if (!w || !h) { w = S; h = S; }
  const scale = Math.min(S / w, S / h);
  const fw = Math.round(w * scale), fh = Math.round(h * scale);
  out.push({ json: { ...it.json, src_w: w, src_h: h, x: Math.floor((S - fw) / 2), y: Math.floor((S - fh) / 2) }, binary: it.binary });
}
return out;

const p = $('Prepare media').first().json;
const plan = $('Check each source').all().map(x => x.json);
const uploads = $('Upload to Shopify').isExecuted ? $('Upload to Shopify').all().map(x => x.json) : [];
const pads = $('Plan the padding').isExecuted ? $('Plan the padding').all().map(x => x.json) : [];
let k = 0;
const media = [], notes = [];
for (const m of plan) {
  if (m.blocked) {
    const u = uploads[k] || {}, pad = pads[k] || {};
    k++;
    // A failed download or upload keeps the wsrv.nl URL; the READY check then records the failure.
    if (u.error || pad.pad_error) { notes.push('staging failed for ' + m.source_url); media.push(m); }
    else media.push({ ...m, originalSource: m.resource_url, staged: true });
  } else { if (m.stage_error) notes.push(m.stage_error); media.push(m); }
}
return [{ json: { ...p, media, notes } }];

