const s = $('Publish settings').first().json;
const tok = $('Get Shopify token for Publish').first().json;
const p = $('Collect the media').first().json;
const before = new Set($('Prepare media').first().json.before_ids);
const r = $input.first().json;
const pu = ((r.data || {}).productUpdate) || {};
const errors = (pu.userErrors || []).concat(r.errors || []);
const created = (((pu.product || {}).media || {}).nodes || []).filter(n => !before.has(n.id));
const ids = created.map(n => n.id);
const Q = 'query M($ids: [ID!]!) { nodes(ids: $ids) { id ... on MediaImage { status alt mediaErrors { code message } } } }';
const sleep = ms => new Promise(res => setTimeout(res, ms));
const deadline = Date.now() + s.max_wait_seconds * 1000;
let byId = {};
while (ids.length) {
  const q = await this.helpers.httpRequest({ method: 'POST', url: 'https://' + s.store_domain + '/admin/api/2026-10/graphql.json',
    headers: { 'X-Shopify-Access-Token': tok.access_token }, body: { query: Q, variables: { ids } }, json: true, timeout: 60000 });
  byId = {};
  (((q.data || {}).nodes) || []).forEach(n => { if (n) byId[n.id] = n; });
  if (ids.every(id => ['READY', 'FAILED'].includes((byId[id] || {}).status)) || Date.now() > deadline) break;
  await sleep(5000);
}
// Shopify adds media in the order given; the alt text (unique per product) is the cross-check.
const results = created.map((n, i) => {
  const m = p.media.find(x => x.alt === n.alt) || p.media[i] || {};
  const st = byId[n.id] || {};
  return { media_id: n.id, status: st.status || 'MISSING', source_hash: m.source_hash, source_url: m.source_url, filename: m.filename, alt: m.alt,
    primary: !!m.primary, error: (st.mediaErrors || []).map(e => e.code + ': ' + e.message).join('; ') };
});
const ready = results.filter(x => x.status === 'READY');
const failed = results.filter(x => x.status === 'FAILED' || x.status === 'MISSING');
const waiting = results.length - ready.length - failed.length;
const problems = errors.map(e => e.message).concat(p.notes || [],
  failed.map(x => 'Shopify could not fetch ' + x.source_url + (x.error ? ' (' + x.error + ')' : '')));
if (!created.length && !errors.length) problems.push('no media created');
const allReady = results.length > 0 && ready.length === results.length;
return [{ json: {
  product_id: p.product_id, title: p.title, card_channel: p.card_channel, card_ts: p.card_ts, store_url: p.store_url,
  remove_media_id: p.remove_media_id, remove_failed: p.remove_failed, results, all_ready: allReady,
  primary_id: (ready.find(x => x.primary) || {}).media_id || '',
  status: allReady ? 'pushed' : (failed.length || errors.length || !results.length ? 'failed' : 'approved'),
  error: (waiting ? waiting + ' image(s) still processing; the next run checks again. ' : '') + problems.join('; ')
} }];

