const imgs = (Array.isArray(c.images) ? c.images : []).filter(x => x && x.url).slice(0, 10);
const T = 300, G = 12, C = Math.min(3, Math.max(imgs.length, 1));
const rows = Math.ceil(imgs.length / C);
const W = C * T + (C + 1) * G, H = rows * T + (rows + 1) * G;
return imgs.map((x, k) => ({ json: {
  n: String(x.label || (k + 1)),
  tile_url: 'https://wsrv.nl/?url=' + encodeURIComponent(x.url) + '&w=' + T + '&h=' + T + '&fit=contain&cbg=white&output=jpg&q=85',
  x: G + (k % C) * (T + G), y: G + Math.floor(k / C) * (T + G),
  sheet_w: W, sheet_h: H, title: c.title || 'Images'
