const items = $input.all();
const plan = $('Plan tiles').all().map(i => i.json);
// A tile that couldn't be fetched leaves a gap; its number stays with its place on the card.
const ok = items.map((it, k) => ({ it, k })).filter(x => x.it.binary && x.it.binary.data);
if (!ok.length) throw new Error('no tiles could be fetched');
const binary = { data: ok[0].it.binary.data };
const pos = [];
for (let k = 0; k < 10; k++) {
  const x = ok[k];
  if (x) { binary['t' + (k + 1)] = x.it.binary.data; pos.push({ x: plan[x.k].x, y: plan[x.k].y, p: 't' + (k + 1) }); }
  else pos.push({ x: 20000, y: 20000, p: 't1' }); // unused slots land off the canvas
}
return [{ json: { sheet_w: plan[0].sheet_w, sheet_h: plan[0].sheet_h, title: plan[0].title, pos }, binary }];

const s = $('Alt text settings').first().json;
const tok = $('Get Shopify token for Alt text').first().json;
const queued = new Set($input.all().map(i => i.json.media_id).filter(Boolean));
const Q = 'query Media($after: String, $q: String) { products(first: 50, after: $after, query: $q) { pageInfo { hasNextPage endCursor } nodes { id title vendor media(first: 20) { nodes { id alt status mediaContentType preview { image { url } } } } } } }';
const weak = (alt, title, all) => {
  const a = String(alt || '').trim();
  if (!a) return 'empty';
  if (a.toLowerCase() === String(title).trim().toLowerCase()) return 'same as the title';
  if (/\.(jpe?g|png|webp|gif)\b|^(img|dsc|image)[-_ ]?\d+/i.test(a)) return 'a file name';
  if (/\b[a-z]{2,8}:[0-9a-f]{6,}\b/i.test(a)) return 'a code';
  if (all.filter(x => String(x || '').trim().toLowerCase() === a.toLowerCase()).length > 1) return 'repeated on the product';
  return '';
};
// Static data keeps the cursor between scheduled runs (it isn't saved on manual runs).
const sd = $getWorkflowStaticData('global');
let after = sd.alt_after || null;
const found = [];
for (let page = 0; page < s.max_pages && found.length < s.batch_size; page++) {
  const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://' + s.store_domain + '/admin/api/2026-10/graphql.json',
    headers: { 'X-Shopify-Access-Token': tok.access_token }, body: { query: Q, variables: { after, q: s.product_query } }, json: true, timeout: 60000 });
  const d = (r.data || {}).products || { nodes: [], pageInfo: {} };
  for (const p of d.nodes) {
    const imgs = p.media.nodes.filter(m => m.mediaContentType === 'IMAGE' && m.status === 'READY' && m.preview && m.preview.image);
    const alts = imgs.map(m => m.alt);
    imgs.forEach((m, k) => {
      const why = weak(m.alt, p.title, alts);
      if (why && !queued.has(m.id) && found.length < s.batch_size) found.push({ json: {
        media_id: m.id, product_id: p.id, title: p.title.replace(/[{}]/g, ''), vendor: String(p.vendor || '').replace(/[{}]/g, ''),
        position: k + 1, old_alt: m.alt || '', why, image_url: m.preview.image.url,
        vision_url: 'https://wsrv.nl/?url=' + encodeURIComponent(m.preview.image.url) + '&w=768&h=768&fit=contain&cbg=white&output=jpg' } });
    });
  }
  if (!d.pageInfo.hasNextPage) { after = null; break; }
  after = d.pageInfo.endCursor;
}
sd.alt_after = after;
return found;

