const imgs = $('Find weak alt text').all().map(i => i.json);
const batch = 'alt-' + new Date().toISOString().slice(0, 16);
const used = new Set();
return $input.all().map((it, i) => {
  const m = imgs[i];
  // the parsed object (bare JSON reply) or { text } (JSON in a code fence)
  let v = it.json.text === undefined && it.json.alt_text !== undefined ? it.json : null;
  if (!v && it.json.text !== undefined) { const t = String(it.json.text); try { v = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); } catch (e) {} }
  let a = String((v && v.alt_text) || '').replace(/\s+/g, ' ').trim().replace(/^["']|["']$/g, '');
  const view = String((v && v.view) || '').trim();
  const problems = [];
  if (!a) problems.push('no alt text (the model may not recognise the product)');
  if (a.length > 125) problems.push('too long');
  if (/^(an? )?(image|picture|photo) of\b/i.test(a)) problems.push('starts with image of');
  if (a.toLowerCase() === m.title.toLowerCase()) problems.push('same as the title');
  if (a && used.has(m.product_id + '|' + a.toLowerCase())) a = a.replace(/[.\s]+$/, '') + ', ' + (view || 'photo ' + m.position);
  used.add(m.product_id + '|' + a.toLowerCase());
  return { json: { ...m, new_alt: problems.length ? '' : a, problems: problems.join('; '), batch_id: batch,
    status: problems.length ? 'failed' : 'pending', updated_at: new Date().toISOString() } };
});

