const s = $('Alt text settings').first().json;
const rows = $('Check the alt text').all().map(i => i.json);
const ok = rows.filter(r => r.status === 'pending');
const bad = rows.filter(r => r.status === 'failed');
const line = r => '*' + r.title.slice(0, 60) + '* (photo ' + r.position + ', ' + r.why + ')\n~' + (r.old_alt || 'empty').slice(0, 80) + '~ → ' + r.new_alt;
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'Alt text to review: ' + ok.length + ' images' } },
  ...ok.slice(0, 45).map(r => ({ type: 'section', text: { type: 'mrkdwn', text: line(r) }, accessory: { type: 'image', image_url: r.image_url, alt_text: r.new_alt } })),
  ...(bad.length ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: bad.length + ' image(s) need a person: ' + bad.slice(0, 5).map(r => r.title + ' (' + r.problems + ')').join('; ') }] }] : []),
  ...(ok.length ? [{ type: 'actions', elements: [
    { type: 'button', style: 'primary', text: { type: 'plain_text', text: 'Approve all' }, action_id: 'alt_apply', value: rows[0].batch_id },
    { type: 'button', text: { type: 'plain_text', text: 'Skip' }, action_id: 'alt_skip', value: rows[0].batch_id }
  ] }] : [])
];
return [{ json: { channel: s.slack_channel, text: 'Alt text to review', blocks } }];
